-- 0068 — BÁO CÁO THEO THU NGÂN, THỐNG KÊ ĐẶT LỊCH, THỐNG KÊ DÙNG DỊCH VỤ (giống SalonHero).
-- Thu ngân của hoá đơn SalonHero = người HOÀN TẤT đơn (completed_by), không phải người lập: đã đối chiếu tháng 10/2025 với báo cáo
-- "Doanh thu theo thu ngân" của SalonHero (khớp từng người cả số đơn lẫn tiền). Dữ liệu này nằm ngoài DB nên điền một lần ở đây
-- (lấy từ bản xuất salonhero-20261028-1753); hoá đơn tạo trong app thì thu ngân = người lập (nguoi_lap_id).
-- Mã người dùng SalonHero bị dùng lại cho nhiều người qua các năm (vd một tài khoản "Thu ngân Đà Lạt") nên báo cáo gom theo mã, hiện tên mới nhất trong kỳ.
-- Doanh số = tiền hàng − giảm giá cả đơn (giống bc_doanh_thu_ngay); "Doanh thu sau trừ thẻ" = doanh số − phần trả bằng thẻ tiền = cột "Doanh thu" của SalonHero.

alter table public.hoa_don add column thu_ngan_sh_id bigint, add column thu_ngan_ten text;

-- Chỉ mục theo ngày cho báo cáo mọi chi nhánh (chỉ mục cũ bắt đầu bằng chi_nhanh_id nên không dùng được khi không lọc chi nhánh).
-- (cùng định nghĩa với 0067 nên dùng if not exists: nhánh nào chạy trước cũng được)
create index if not exists hoa_don_ngay_tao_idx on public.hoa_don (ngay_hd desc, tao_luc desc);
create index if not exists lich_hen_bat_dau_idx on public.lich_hen (bat_dau);
create index if not exists buoi_ngay_lam_idx on public.buoi_thuc_hien (ngay_lam) where trang_thai = 'da_lam';

-- ───────── Điền thu ngân cho hoá đơn SalonHero đã nhập (không làm gì trên DB trống) ─────────
-- Tắt trigger người dùng của hoa_don trong lúc điền (chỉ đổi 2 cột báo cáo): tránh bắn 45 nghìn cảnh báo realtime làm app đọc lại giữa chừng → khoá chéo.
alter table public.hoa_don disable trigger user;
