drop table _ten_nguoi;
alter table public.hoa_don enable trigger user;

-- ───────── D1. Theo thu ngân ─────────
-- p_nhom: 'tong' (cả kỳ) | 'thang' | 'ngay' → cột ky. Mỗi dòng = một thu ngân trong một kỳ.
create function public.bc_thu_ngan(p_tu date, p_den date, p_cn uuid default null, p_nhom text default 'tong')
returns table (ky date, khoa text, thu_ngan text, cac_ten text, so_don int, doanh_so bigint, tru_the_tien bigint, doanh_thu bigint, con_no bigint, da_thu bigint)
language sql stable as $$
  with hd as (
    select h.ngay_hd,
           case when h.thu_ngan_sh_id is not null then 'sh:' || h.thu_ngan_sh_id
                when h.thu_ngan_ten is not null then 'ten:' || h.thu_ngan_ten
                else 'nv:' || h.nguoi_lap_id end as khoa,
           coalesce(h.thu_ngan_ten, n.ho_ten, 'Chưa rõ') as ten,
           greatest(h.tong_hang - h.giam_gia_don, 0) as doanh_so,
           case when h.la_lich_su then h.tien_tru_the
                else coalesce((select sum(case t.loai when 'thu' then t.so_tien else -t.so_tien end) from public.thanh_toan t
                                where t.hoa_don_id = h.id and t.phuong_thuc = 'the_tien'), 0) end as tru_the,
           h.con_no
      from public.hoa_don h left join public.nhan_vien n on n.id = h.nguoi_lap_id
     where h.trang_thai = 'hoan_thanh' and not h.la_so_du_dau and h.ngay_hd between p_tu and p_den and (p_cn is null or h.chi_nhanh_id = p_cn))
  select case p_nhom when 'ngay' then hd.ngay_hd when 'thang' then date_trunc('month', hd.ngay_hd)::date else p_tu end,
         hd.khoa, (array_agg(hd.ten order by hd.ngay_hd desc))[1], string_agg(distinct hd.ten, ', '),
         count(*)::int, sum(hd.doanh_so)::bigint, sum(hd.tru_the)::bigint, sum(hd.doanh_so - hd.tru_the)::bigint,
         sum(hd.con_no)::bigint, sum(hd.doanh_so - hd.tru_the - hd.con_no)::bigint
    from hd group by 1, 2 order by 1, 8 desc
$$;

-- ───────── D2. Thống kê đặt lịch ─────────
-- Dạng dài (chieu, khoa, nhan): 'tong' | 'trang_thai' | 'nguon' | 'nhan_vien' | 'chi_nhanh' | 'ky' (ngày hoặc tháng theo p_nhom). Lịch tính theo giờ hẹn (giờ Việt Nam).
create function public.bc_dat_lich(p_tu date, p_den date, p_cn uuid default null, p_nhom text default 'thang')
returns table (chieu text, khoa text, nhan text, so_lich int, hoan_thanh int, huy int, khong_den int, chua_den int)
language sql stable as $$
  with l as (
    select l.trang_thai, coalesce(nullif(l.nguon_dat, ''), nullif(l.nguon, ''), 'KHAC') as nguon,
           coalesce(l.nhan_vien_id::text, 'ten:' || nullif(l.nhan_vien_ten, ''), '') as nv_khoa,
           coalesce(n.ho_ten, nullif(l.nhan_vien_ten, ''), 'Chưa gán nhân viên') as nv_ten,
           l.chi_nhanh_id::text as cn_khoa, c.ten as cn_ten,
           case when p_nhom = 'ngay' then (l.bat_dau at time zone 'Asia/Ho_Chi_Minh')::date
                else date_trunc('month', l.bat_dau at time zone 'Asia/Ho_Chi_Minh')::date end::text as ky
      from public.lich_hen l
      left join public.nhan_vien n on n.id = l.nhan_vien_id
      join public.chi_nhanh c on c.id = l.chi_nhanh_id
     where l.bat_dau >= (p_tu::timestamp at time zone 'Asia/Ho_Chi_Minh') and l.bat_dau < ((p_den + 1)::timestamp at time zone 'Asia/Ho_Chi_Minh')
       and (p_cn is null or l.chi_nhanh_id = p_cn))
  select case when grouping(l.trang_thai) = 0 then 'trang_thai' when grouping(l.nguon) = 0 then 'nguon' when grouping(l.nv_khoa) = 0 then 'nhan_vien'
              when grouping(l.cn_khoa) = 0 then 'chi_nhanh' when grouping(l.ky) = 0 then 'ky' else 'tong' end,
         coalesce(l.trang_thai, l.nguon, l.nv_khoa, l.cn_khoa, l.ky, ''),
         coalesce(l.trang_thai, l.nguon, l.nv_ten, l.cn_ten, l.ky, 'Tổng'),
         count(*)::int,
         count(*) filter (where l.trang_thai = 'hoan_thanh')::int,
         count(*) filter (where l.trang_thai = 'huy')::int,
         count(*) filter (where l.trang_thai = 'khong_den')::int,
         count(*) filter (where l.trang_thai not in ('hoan_thanh', 'huy', 'khong_den'))::int
    from l
   group by grouping sets ((), (l.trang_thai), (l.nguon), (l.nv_khoa, l.nv_ten), (l.cn_khoa, l.cn_ten), (l.ky))
   order by 1, 4 desc, 2
$$;

-- ───────── D3. Thống kê dùng dịch vụ ─────────
-- Lượt dịch vụ = dòng dịch vụ trên hoá đơn (SalonHero: dòng có thẻ hoặc giá 0 là "dùng thẻ"; còn lại là trả tiền) + buổi trừ thẻ làm trong app.
-- Doanh số chỉ có ở lượt trả tiền (đã chia giảm giá cả đơn). "Giá trị thẻ" = số buổi × giá trị một buổi của thẻ (ước tính, thẻ không giới hạn buổi = 0).
-- Nhân viên = người phục vụ (dong_nhan_vien vai 'phuc_vu' hoặc người làm buổi); tiền chia theo tỉ lệ, lượt tính đủ cho mỗi người.
create function public.bc_dung_dich_vu(p_tu date, p_den date, p_cn uuid default null, p_nhom text default 'thang')
returns table (chieu text, khoa text, nhan text, luot_the bigint, luot_tien bigint, doanh_so bigint, gia_tri_the bigint)
language sql stable as $$
  with x0 as (
    select d.id as dong_id, h.ngay_hd as ngay, h.chi_nhanh_id, coalesce(d.dich_vu_id::text, 'ten:' || d.ten) as dv_khoa, coalesce(dv.ten, d.ten) as dv_ten,
           (d.the_khach_sh_id is not null or d.thanh_tien = 0) as dung_the, d.so_luong::bigint as sl,
           case when d.the_khach_sh_id is not null or d.thanh_tien = 0 then 0
                else d.thanh_tien * case when h.tong_hang > 0 then (h.tong_hang - h.giam_gia_don)::numeric / h.tong_hang else 0 end end as doanh_so,
           case when d.the_khach_sh_id is not null or d.thanh_tien = 0
                then d.so_luong::numeric * coalesce((select t.gia_tri_buoi from public.the_khach t where t.sh_id = d.the_khach_sh_id and t.so_buoi_tong < 999999), 0) else 0 end as gia_tri,
           null::uuid as nv_buoi, h.ngay_hd as ky_ngay
      from public.hoa_don_dong d join public.hoa_don h on h.id = d.hoa_don_id left join public.dich_vu dv on dv.id = d.dich_vu_id
     where d.loai = 'dich_vu' and h.trang_thai = 'hoan_thanh' and not h.la_so_du_dau and h.ngay_hd between p_tu and p_den and (p_cn is null or h.chi_nhanh_id = p_cn)
    union all
    select null, b.ngay_lam, b.chi_nhanh_id, b.dich_vu_id::text, dv.ten, true, 1, 0, b.doanh_thu_buoi, b.nv_thuc_hien_id, b.ngay_lam
      from public.buoi_thuc_hien b join public.dich_vu dv on dv.id = b.dich_vu_id
     where b.trang_thai = 'da_lam' and b.ngay_lam between p_tu and p_den and (p_cn is null or b.chi_nhanh_id = p_cn)),
  x as (select x0.*, (case when p_nhom = 'ngay' then x0.ky_ngay else date_trunc('month', x0.ky_ngay)::date end)::text as ky from x0),
  chung as (
    select case when grouping(x.dv_khoa) = 0 then 'dich_vu' when grouping(x.chi_nhanh_id) = 0 then 'chi_nhanh' when grouping(x.ky) = 0 then 'ky' else 'tong' end as chieu,
           coalesce(x.dv_khoa, x.chi_nhanh_id::text, x.ky, '') as khoa,
           coalesce(x.dv_ten, (select c.ten from public.chi_nhanh c where c.id = x.chi_nhanh_id), x.ky, 'Tổng') as nhan,
           coalesce(sum(x.sl) filter (where x.dung_the), 0)::bigint as luot_the, coalesce(sum(x.sl) filter (where not x.dung_the), 0)::bigint as luot_tien,
           coalesce(round(sum(x.doanh_so)), 0)::bigint as doanh_so, coalesce(round(sum(x.gia_tri)), 0)::bigint as gia_tri
      from x
     group by grouping sets ((), (x.dv_khoa, x.dv_ten), (x.chi_nhanh_id), (x.ky))),
  theo_nv as (
    select coalesce(p.nv::text, '') as khoa, coalesce(n.ho_ten, 'Chưa gán người làm') as nhan,
           coalesce(sum(x.sl) filter (where x.dung_the), 0)::bigint as luot_the, coalesce(sum(x.sl) filter (where not x.dung_the), 0)::bigint as luot_tien,
           coalesce(round(sum(x.doanh_so * p.ti_le / 100)), 0)::bigint as doanh_so, coalesce(round(sum(x.gia_tri * p.ti_le / 100)), 0)::bigint as gia_tri
      from x
      cross join lateral (
        select c.nhan_vien_id as nv, c.ti_le from public.dong_nhan_vien c where c.dong_id = x.dong_id and c.vai = 'phuc_vu'
        union all select x.nv_buoi, 100 where x.nv_buoi is not null
        union all select null, 100 where x.nv_buoi is null and not exists (select 1 from public.dong_nhan_vien c where c.dong_id = x.dong_id and c.vai = 'phuc_vu')) p
      left join public.nhan_vien n on n.id = p.nv
     group by 1, 2)
  select * from (select * from chung union all select 'nhan_vien', khoa, nhan, luot_the, luot_tien, doanh_so, gia_tri from theo_nv) k
   order by k.chieu, k.luot_the + k.luot_tien desc, k.khoa
$$;

select public.khoa_tat_ca_bang();
